/**
 * Writing generated files beside the user's sources (Convert to CSP, graph
 * exports) without following symbolic links. A workspace can contain
 * `demo.csp -> ~/.config/something`; writing through it would create or
 * overwrite a file anywhere the user can write.
 *
 * A new file is created exclusively and without following a link, so an
 * existing name (a dangling link included) makes the create fail instead of
 * writing through it. A file this server generated before is replaced by
 * writing a fresh file next to it and renaming it over the old name: the
 * rename replaces the name itself, so a link put there in between is
 * replaced, never followed. The generator check reads the old file without
 * following a link either.
 */
import { randomBytes } from 'node:crypto';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { isBrowserMode } from './mode';

export type GeneratedWrite = { written: true } | { written: false; reason: string };

/** Bytes of an existing file that `ours` is shown, to recognise a file this server generated. */
const HEAD_BYTES = 4096;

/** O_NOFOLLOW where the platform has it (not on Windows, where a link is not followed by these calls anyway). */
const NOFOLLOW = fs.constants.O_NOFOLLOW ?? 0;

/**
 * Write `content` to `file` when there is no file of that name, or when the
 * file there is a regular file whose first bytes `ours` recognises as
 * generated by this server. Anything else (a symbolic link, a directory, a
 * file the user wrote) is left alone and the reason returned.
 */
export function writeGeneratedFile(file: string, content: string, ours: (head: string) => boolean): GeneratedWrite {
  if (isBrowserMode()) return writeInMemory(file, content, ours);
  let stat: fs.Stats | undefined;
  try {
    stat = fs.lstatSync(file);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') return { written: false, reason: errorText(error) };
  }
  if (!stat) {
    try {
      writeExclusive(file, content);
      return { written: true };
    } catch (error) {
      // Something took the name since the check: it is not ours to replace.
      return { written: false, reason: (error as NodeJS.ErrnoException).code === 'EEXIST' ? 'it appeared while it was being written' : errorText(error) };
    }
  }
  if (stat.isSymbolicLink()) return { written: false, reason: 'it is a symbolic link' };
  if (!stat.isFile()) return { written: false, reason: 'it is not a regular file' };
  let head: string;
  try {
    head = readHead(file);
  } catch (error) {
    return { written: false, reason: (error as NodeJS.ErrnoException).code === 'ELOOP' ? 'it is a symbolic link' : errorText(error) };
  }
  if (!ours(head)) return { written: false, reason: 'it was not written by processj-lsp' };
  const temp = path.join(path.dirname(file), `.${path.basename(file)}.${randomBytes(6).toString('hex')}.tmp`);
  try {
    writeExclusive(temp, content);
    fs.renameSync(temp, file);
    return { written: true };
  } catch (error) {
    try {
      fs.rmSync(temp, { force: true });
    } catch {
      /* best effort */
    }
    return { written: false, reason: errorText(error) };
  }
}

/** Whether `file` exists and is a regular file whose first bytes `ours` recognises (links are not followed). */
export function isGeneratedFile(file: string, ours: (head: string) => boolean): boolean {
  try {
    if (isBrowserMode()) return ours(fs.readFileSync(file, 'utf8').slice(0, HEAD_BYTES));
    return fs.lstatSync(file).isFile() && ours(readHead(file));
  } catch {
    return false;
  }
}

function writeExclusive(file: string, content: string): void {
  const handle = fs.openSync(file, fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | NOFOLLOW, 0o666);
  try {
    fs.writeFileSync(handle, content);
  } finally {
    fs.closeSync(handle);
  }
}

function readHead(file: string): string {
  const handle = fs.openSync(file, fs.constants.O_RDONLY | NOFOLLOW);
  try {
    if (!fs.fstatSync(handle).isFile()) throw Object.assign(new Error('not a regular file'), { code: 'EISDIR' });
    const head = Buffer.alloc(HEAD_BYTES);
    const size = fs.readSync(handle, head, 0, head.length, 0);
    return head.subarray(0, size).toString('utf8');
  } finally {
    fs.closeSync(handle);
  }
}

/** The browser's in-memory project has no links and no other writer: the same rules, with the calls it offers. */
function writeInMemory(file: string, content: string, ours: (head: string) => boolean): GeneratedWrite {
  if (fs.existsSync(file) && !isGeneratedFile(file, ours)) return { written: false, reason: 'it was not written by processj-lsp' };
  fs.writeFileSync(file, content);
  return { written: true };
}

function errorText(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
